import {Field, Form} from 'alinea'
import {IcRoundStarOutline} from 'alinea/dashboard/icons'

export const Rating = Form.input('Rating', {
  icon: IcRoundStarOutline,
  kind: 'number',
  settings: {
    max: Field.number('Maximum', {initialValue: 5})
  },
  parse([raw]) {
    if (typeof raw !== 'string' || raw === '') return undefined
    const value = Number(raw)
    return Number.isInteger(value) ? value : undefined
  },
  attributes: settings => ({type: 'number', min: 1, max: settings.max ?? 5}),
  validate(value, settings) {
    const max = settings.max ?? 5
    if (value < 1 || value > max) return `Choose 1 to ${max}`
  }
})

import {Form} from 'alinea'
import {Rating} from './Rating'

export const FormEntry = Form.type('Form', {
  inputs: {...Form.defaults, rating: Rating}
})

'use client'

import {Form, type FormInputViewProps, type FormProps} from 'alinea/ui'

function RatingInput({input, name, error, disabled}: FormInputViewProps) {
  const max = Number(input.settings.max ?? 5)
  return (
    <fieldset data-input="rating" data-invalid={error ? '' : undefined}>
      <legend>
        {input.label}
        {input.required && ' *'}
      </legend>
      {Array.from({length: max}, (_, index) => (
        <label key={index}>
          <input
            type="radio"
            name={name}
            value={index + 1}
            required={input.required}
            disabled={disabled}
          />
          {index + 1}
        </label>
      ))}
      {error && <p role="alert">{error}</p>}
    </fieldset>
  )
}

const views = {rating: RatingInput}

export function RatedForm(props: Omit<FormProps, 'views'>) {
  return <Form {...props} views={views} />
}
